        require(amount <= address(this).balance);
        uint balBefore = address(c).balance;

        bool reverted;
        try c.sendTo{value: amount}(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool expectedRevert =
            msg.sender != ownerOfC() ||
