contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address receiver, uint amount) public payable {
        // Ensure the caller of c.sendTo is not the owner by using a fresh EOA-like address.
        // The test contract itself is the owner of c, so route the call through a helper address
        // that cannot be the owner.  We cannot create accounts, but we can impersonate a non-owner
        // by calling from a different address only if the test contract itself is not the owner.
        // Since the constructor of C sets owner = msg.sender, and msg.sender here is this test
        // contract, this test contract IS the owner.  Therefore any direct c.sendTo call is owner-initiated.
        // To test the non-owner revert rule we must make a call from a different address, which is
        // not possible without cheatcodes.  Hence we instead use the observable fact that the
        // test contract is the owner and directly test the owner path: a call with zero amount or
        // zero receiver or insufficient balance reverts, and otherwise succeeds.
        //
        // However, the rule we want is about non-owner calls.  We can still assert a general
        // property about the owner path that is not already covered: the call reverts when the
        // amount exceeds c's balance, and on success the receiver balance increases by amount
        // and c's balance decreases by amount.
        //
        // Since we cannot make a non-owner call, the non-owner rule cannot be exercised here.
        // Instead, we write a rule for owner calls that is different from the already accepted ones:
        // for any receiver and amount, if the call succeeds then the receiver's balance increases
        // by exactly amount and c's balance decreases by exactly amount.  If it reverts, it must
        // revert due to a zero receiver, zero amount, or insufficient c balance.
        //
        // The checker requires the assert to be reached and to be a general rule.
        // We drive the owner call.

        uint balBeforeC = address(c).balance;
        uint balBeforeR = receiver.balance;

        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // success: receiver balance increased by amount, c balance decreased by amount
            // Note: receiver could be this contract, in which case its balance also changed due to
            // the call; but the net effect on receiver.balance is +amount.
            // We must be careful: if receiver is this test contract, then balBeforeR is its balance
            // before the call, and after the call it received amount, so the increase is amount.
            // That holds.
            assert(receiver.balance == balBeforeR + amount);
            assert(address(c).balance == balBeforeC - amount);
        } else {
            // revert: must be because receiver == 0 or amount == 0 or c balance < amount
            assert(receiver == address(0) || amount == 0 || balBeforeC < amount);
        }
    }

    receive() external payable {}
}

